  position: absolute;
}

.dgtx-switch {
  align-items: center;
  background: #f8f9fa;
  display: inline-flex;
  height: 100%;
  position: relative;
  width: auto;
}

.dgtx-switch .form-check {
  padding: 0;
  height: 100%;
}

.dgtx-switch .form-check input[type="radio"] {
  display: none;
}

.dgtx-switch .form-check label {
  align-items: center;
  color: #ced4da;
  cursor: pointer;
  display: flex;
  justify-content: center;
  height: 100%;
  position: relative;
  width: 80px;
  z-index: 3;
}

.dgtx-switch .form-check label.checked {
  color: #FFFFFF;
}

.dgtx-switch::before {
  content: " ";
  display: flex;
  height: 100%;
  position: absolute;
  transition: all ease .3s;
  margin-left: 0;
  width: 80px;
  z-index: 2;
}

.dgtx-switch.dgtx-switch-yes::before {
  background-color: #0d6efd;
}

.dgtx-switch.dgtx-switch-no::before {
  margin-left: 80px;
}

